function LoginModal({ onClose, onLogin }) {
  const [loading, setLoading] = useState(false);
  const [error, setError]     = useState('');

  const doLogin = async () => {
    setLoading(true);
    setError('');
    try {
      // 必須在 Electron 環境才能開啟 OAuth 視窗
      if (!window.electronAPI?.microsoftLogin) {
        setError('登入功能僅在完整安裝版本中可用，請先執行 npm run pack 打包。');
        setLoading(false);
        return;
      }
      const res = await window.electronAPI.microsoftLogin();
      if (res.success) {
        onLogin(res.auth);
      } else {
        setError(res.error || '登入失敗，請稍後再試。');
      }
    } catch(e) {
      setError('登入視窗異常，請聯絡管理員。\n' + e.message);
    }
    setLoading(false);
  };

  return (
    <Modal title="🪟 微軟帳號登入" onClose={loading ? undefined : onClose} width={420}>
      <div style={{padding:28,display:"flex",flexDirection:"column",gap:18}}>
        <p style={{color:C.sub,fontSize:14,margin:0}}>
          使用您的 Microsoft / Xbox 帳號登入以驗證正版資格。
        </p>
        <div style={{
          background:"rgba(255,255,255,.05)",borderRadius:14,padding:24,
          textAlign:"center",border:`1px dashed ${C.border}`,
        }}>
          <div style={{fontSize:44,marginBottom:10}}>🪟</div>
          <div style={{color:C.text,fontWeight:700,fontSize:16,marginBottom:6}}>Microsoft OAuth 驗證</div>
          <div style={{color:C.sub,fontSize:13,marginBottom:18,lineHeight:1.7}}>
            點擊下方按鈕將開啟微軟登入視窗，<br/>完成後自動返回啟動器。
          </div>
          {error && (
            <div style={{
              background:"rgba(239,68,68,.1)",border:"1px solid rgba(239,68,68,.3)",
              borderRadius:10,padding:"10px 14px",color:"#fca5a5",
              fontSize:12,marginBottom:14,textAlign:"left",lineHeight:1.6,
              whiteSpace:"pre-wrap",
            }}>
              ❌ {error}
            </div>
          )}
          <Btn color="accent" onClick={doLogin} disabled={loading}
            style={{background:C.accent,color:"#000",width:"100%",fontSize:15}}>
            {loading ? "開啟登入視窗中..." : "使用 Microsoft 帳號登入"}
          </Btn>
        </div>
        <div style={{fontSize:11,color:"#4b5563",textAlign:"center",lineHeight:1.6}}>
          本啟動器不儲存您的密碼，僅保存登入 Token 於本機。
        </div>
      </div>
    </Modal>
  );
}

