function ProfileFormModal({ initial, onClose, onSave, onDelete, isEdit = false }) {
    const [name, setName] = useState(initial?.name || "");
    const [ver, setVer] = useState(initial?.ver || "1.21.11");
    const [minRam, setMinRam] = useState(initial?.minRam || "512");
    const [maxRam, setMaxRam] = useState(initial?.maxRam || "4096");
    const [loader, setLoader] = useState(initial?.loader || "Vanilla");
    const [loaderVer, setLoaderVer] = useState(initial?.loaderVer || "—");
    const [confirmDel, setConfirmDel] = useState(false);
    const [versionList, setVersionList] = useState(["1.21.11"]); // 預設
    const [loadingVers, setLoadingVers] = useState(true);

    useEffect(() => {
        setLoadingVers(true);
        api.getVersions().then(list => {
            if (list && list.length > 0) {
                setVersionList(list);
            }
            setLoadingVers(false);
        }).catch(() => setLoadingVers(false));
    }, []);

  const handleLoaderChange = (v) => { setLoader(v); setLoaderVer(LOADER_VERSIONS[v][0]); };

  return (
    <>
    <Modal title={isEdit ? `⚙️ 設定 — ${initial.name}` : "➕ 新增安裝檔"} onClose={onClose} width={620}>
      <div style={{padding:20,display:"flex",flexDirection:"column",gap:14}}>
        {/* Row 1: name + version + icon */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 88px",gap:12,alignItems:"center"}}>
          <Input value={name} onChange={setName} placeholder="輸入名稱"/>
          <Select value={ver} onChange={setVer} options={loadingVers ? ["載入中..."] : versionList} />
          <div style={{
            border:`2px dashed ${C.border}`,borderRadius:10,height:60,
            display:"flex",alignItems:"center",justifyContent:"center",
            color:C.sub,fontSize:12,cursor:"pointer",flexDirection:"column",gap:2,
          }}>
            <span style={{fontSize:20}}>🖼️</span>
            <span>icon</span>
          </div>
        </div>
        {/* Row 2: RAM */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 24px 1fr",gap:8,alignItems:"center"}}>
          <Input value={minRam} onChange={setMinRam} placeholder="最低記憶體 (MB)"/>
          <span style={{color:C.sub,textAlign:"center",fontSize:16,fontWeight:600}}>~</span>
          <Input value={maxRam} onChange={setMaxRam} placeholder="最高記憶體 (MB)"/>
        </div>
        {/* Row 3: loader */}
        <div style={{borderTop:`1px solid ${C.border}`,paddingTop:12,
          display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
          <Select value={loader} onChange={handleLoaderChange} options={LOADERS}/>
          <Select value={loaderVer} onChange={setLoaderVer} options={LOADER_VERSIONS[loader]}/>
        </div>
        {/* Buttons */}
        <div style={{
          display:"flex",gap:10,justifyContent:isEdit?"space-between":"flex-end",
          paddingTop:4,borderTop:`1px solid ${C.border}`,
        }}>
          {isEdit && (
            <Btn color="red" onClick={()=>setConfirmDel(true)} style={{fontSize:13}}>
              🗑️ 刪除安裝檔
            </Btn>
          )}
          <div style={{display:"flex",gap:10}}>
            <Btn color="gray" onClick={onClose}>{isEdit?"取消":"取消建立"}</Btn>
            <Btn color="green" onClick={()=>{
              if(!name.trim()) return;
              onSave({name,ver,minRam,maxRam,loader,loaderVer});
            }}>
              {isEdit?"儲存":"建立"}
            </Btn>
          </div>
        </div>
      </div>
    </Modal>
    {confirmDel && (
      <DeleteConfirmModal name={initial.name} onClose={()=>setConfirmDel(false)}
        onDelete={()=>{ setConfirmDel(false); onDelete(); }}/>
    )}
    </>
  );
}

// Modrinth API loader mapping
const MODRINTH_LOADER_MAP = {
  Vanilla:  null,        // 原版不支援模組/光影
  Fabric:   "fabric",
  Forge:    "forge",
  NeoForge: "neoforge",
  Quilt:    "quilt",
};

// Tab 設定：各載入器允許的 tab
const TAB_SUPPORT = {
  Vanilla:  { "模組": false, "光影": false, "材質包": true,  "資料包": true  },
  Fabric:   { "模組": true,  "光影": true,  "材質包": true,  "資料包": true  },
  Forge:    { "模組": true,  "光影": false, "材質包": true,  "資料包": true  },
  NeoForge: { "模組": true,  "光影": false, "材質包": true,  "資料包": true  },
  Quilt:    { "模組": true,  "光影": true,  "材質包": true,  "資料包": true  },
};

// Tab → Modrinth project_type
const TAB_TYPE = {
  "模組":   "mod",
  "光影":   "shader",
  "材質包": "resourcepack",
  "資料包": "datapack",
};

function ModrinthModal({ onClose, loader, mcVersion }) {
  const [tab, setTab]       = useState("模組");
  const [query, setQuery]   = useState("");
  const [items, setItems]   = useState([]);
  const [loading, setLoading] = useState(false);
  const [installed, setInst]  = useState(new Set());
  const searchTimer = useRef(null);

  const loaderKey   = loader || "Vanilla";
  const support     = TAB_SUPPORT[loaderKey] || TAB_SUPPORT.Vanilla;
  const modrinthLoader = MODRINTH_LOADER_MAP[loaderKey];
  const isBlocked   = !support[tab];

  // Auto-switch to first supported tab
  useEffect(()=>{
    const firstSupported = ["模組","光影","材質包","資料包"].find(t => support[t]);
    if (!support[tab] && firstSupported) setTab(firstSupported);
  }, [loader]);

  // Fetch from Modrinth API
  const fetchModrinth = useCallback(async (searchQuery, currentTab) => {
    if (!support[currentTab]) { setItems([]); return; }
    setLoading(true);
    try {
      const type = TAB_TYPE[currentTab];
      const facets = [[`project_type:${type}`]];
      if (modrinthLoader && (currentTab === "模組" || currentTab === "光影")) {
        facets.push([`categories:${modrinthLoader}`]);
      }
      if (mcVersion) facets.push([`versions:${mcVersion}`]);

      const params = new URLSearchParams({
        query: searchQuery || "",
        limit: "20",
        index: searchQuery ? "relevance" : "downloads",
        facets: JSON.stringify(facets),
      });

      const res = await fetch(`https://api.modrinth.com/v2/search?${params}`, {
        headers: { "User-Agent": "BlackCatLauncher/1.0.0" }
      });
      const data = await res.json();
      setItems(data.hits || []);
    } catch(e) {
      setItems([]);
    }
    setLoading(false);
  }, [modrinthLoader, mcVersion, support]);

  // Debounced search
  useEffect(()=>{
    if (isBlocked) return;
    clearTimeout(searchTimer.current);
    searchTimer.current = setTimeout(()=>fetchModrinth(query, tab), 400);
    return ()=>clearTimeout(searchTimer.current);
  }, [query, tab, fetchModrinth, isBlocked]);

  const TABS = ["模組","光影","材質包","資料包"];

  return (
    <Modal title={`🔍 Modrinth 資源庫 — ${loaderKey}`} onClose={onClose} width={680}>
      <div style={{display:"flex",height:460}}>
        {/* Sidebar tabs */}
        <div style={{width:88,borderRight:`1px solid ${C.border}`,
          display:"flex",flexDirection:"column",gap:3,padding:"10px 6px",flexShrink:0}}>
          {TABS.map(t=>{
            const blocked = !support[t];
            const active  = tab === t;
            return (
              <button key={t} onClick={()=>{ if(!blocked) setTab(t); }} style={{
                background: active ? "rgba(74,222,128,.15)" : blocked ? "rgba(255,255,255,.02)" : "transparent",
                border: `1px solid ${active ? "rgba(74,222,128,.3)" : "transparent"}`,
                borderRadius:10, padding:"10px 4px",
                color: active ? C.green : blocked ? "#374151" : C.sub,
                fontSize:12, fontWeight:600,
                cursor: blocked ? "not-allowed" : "pointer",
                fontFamily:"inherit", transition:"all .15s",
                opacity: blocked ? 0.4 : 1,
              }}>{t}</button>
            );
          })}
        </div>

        {/* Main content */}
        <div style={{flex:1,display:"flex",flexDirection:"column",minWidth:0}}>
          {isBlocked ? (
            /* Blocked message */
            <div style={{
              flex:1,display:"flex",flexDirection:"column",
              alignItems:"center",justifyContent:"center",gap:12,padding:24,
            }}>
              <div style={{fontSize:36}}>🚫</div>
              <div style={{fontWeight:700,fontSize:15,color:C.text,textAlign:"center"}}>
                與當前載入器不符
              </div>
              <div style={{
                color:C.sub,fontSize:13,textAlign:"center",lineHeight:1.7,
                background:"rgba(255,255,255,.04)",borderRadius:12,
                padding:"16px 24px",border:`1px solid ${C.border}`,maxWidth:300,
              }}>
                <div style={{fontWeight:600,color:"#fbbf24",marginBottom:6}}>
                  與當前載入器不符，無法新增和搜尋
                </div>
                {loaderKey === "Vanilla"
                  ? `原版（Vanilla）不支援${tab}。\n請在安裝檔設定中改用 Fabric 或 Forge 載入器。`
                  : `${loaderKey} 不支援${tab}。\n請切換至支援的載入器後再使用此功能。`
                }
              </div>
            </div>
          ) : (
            <>
              {/* Search bar */}
              <div style={{padding:"10px 12px",borderBottom:`1px solid ${C.border}`,flexShrink:0}}>
                <input value={query} onChange={e=>setQuery(e.target.value)}
                  placeholder={`🔍 搜尋 ${tab}...`}
                  style={{
                    background:"rgba(255,255,255,.07)",border:`1px solid ${C.border}`,
                    borderRadius:20,padding:"8px 16px",color:C.text,fontSize:13,
                    fontFamily:"inherit",outline:"none",width:"100%",boxSizing:"border-box",
                  }}/>
              </div>

              {/* Results */}
              <div style={{overflow:"auto",flex:1,padding:8}}>
                {loading && (
                  <div style={{color:C.sub,textAlign:"center",paddingTop:40,fontSize:14}}>
                    載入中...
                  </div>
                )}
                {!loading && items.length===0 && (
                  <div style={{color:C.sub,textAlign:"center",paddingTop:40,fontSize:14}}>
                    {query ? "沒有符合的結果" : "輸入關鍵字搜尋"}
                  </div>
                )}
                {!loading && items.map(item=>(
                  <div key={item.project_id} style={{
                    display:"flex",alignItems:"center",gap:12,padding:"10px",
                    borderRadius:10,marginBottom:4,
                    background:installed.has(item.project_id)?"rgba(74,222,128,.07)":"rgba(255,255,255,.04)",
                    border:`1px solid ${installed.has(item.project_id)?"rgba(74,222,128,.2)":"transparent"}`,
                  }}>
                    {/* Icon */}
                    {item.icon_url ? (
                      <img src={item.icon_url} alt="" style={{
                        width:40,height:40,borderRadius:8,objectFit:"cover",flexShrink:0,
                      }} onError={e=>e.target.style.display='none'}/>
                    ) : (
                      <div style={{width:40,height:40,borderRadius:8,background:"rgba(255,255,255,.08)",
                        display:"flex",alignItems:"center",justifyContent:"center",
                        fontSize:20,flexShrink:0}}>📦</div>
                    )}
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontWeight:600,fontSize:14,color:C.text}}>{item.title}</div>
                      <div style={{fontSize:12,color:C.sub,overflow:"hidden",
                        textOverflow:"ellipsis",whiteSpace:"nowrap",marginTop:1}}>
                        {item.description}
                      </div>
                      <div style={{fontSize:11,color:"#6b7280",marginTop:2,display:"flex",gap:8}}>
                        <span>⬇️ {(item.downloads||0).toLocaleString()}</span>
                        <span>👍 {(item.follows||0).toLocaleString()}</span>
                      </div>
                    </div>
                    <button
                      onClick={()=>setInst(s=>{
                        const n=new Set(s);
                        n.has(item.project_id)?n.delete(item.project_id):n.add(item.project_id);
                        return n;
                      })}
                      style={{
                        background:installed.has(item.project_id)?"rgba(239,68,68,.2)":"rgba(74,222,128,.2)",
                        border:`1px solid ${installed.has(item.project_id)?C.red:C.green}`,
                        color:installed.has(item.project_id)?C.red:C.green,
                        borderRadius:8,padding:"5px 14px",fontSize:13,fontWeight:600,
                        cursor:"pointer",fontFamily:"inherit",flexShrink:0,
                      }}>
                      {installed.has(item.project_id)?"移除":"安裝"}
                    </button>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </Modal>
  );
}

function ContextMenu({ x, y, onSettings, onDelete, onClose }) {
  useEffect(()=>{
    const h = () => onClose();
    window.addEventListener("mousedown", h);
    return () => window.removeEventListener("mousedown", h);
  },[]);
  const item = (label, fg, onClick) => (
    <button onClick={(e)=>{e.stopPropagation();onClick();}} style={{
      display:"block",width:"100%",background:"none",border:"none",
      color:fg,fontSize:14,padding:"10px 16px",cursor:"pointer",
      textAlign:"left",fontFamily:"inherit",transition:"background .1s",
    }}
    onMouseEnter={e=>e.currentTarget.style.background="rgba(255,255,255,.07)"}
    onMouseLeave={e=>e.currentTarget.style.background="none"}
    >{label}</button>
  );
  return (
    <div onMouseDown={e=>e.stopPropagation()} style={{
      position:"fixed",left:x,top:y,background:C.panelDark,
      border:`1px solid ${C.border}`,borderRadius:10,zIndex:2000,
      minWidth:130,boxShadow:"0 8px 32px rgba(0,0,0,.7)",overflow:"hidden",
    }}>
      {item("⚙️ 設定", C.text, onSettings)}
      {item("🗑️ 刪除", C.red, onDelete)}
    </div>
  );
}

