// ─── Install Progress Modal ───────────────────────────────────────────────────
function InstallProgressModal({ profileName, progress, onClose }) {
  const stages = { java:"準備 Java", version:"取得版本資訊", jar:"下載遊戲本體", libraries:"下載 Libraries", assets:"下載資源檔案", loader:"安裝載入器", done:"完成", error:"發生錯誤" };
  const isDone  = progress?.stage === 'done';
  const isError = progress?.stage === 'error';
  return (
    <Modal title={`⬇️ 安裝 ${profileName}`} onClose={isDone||isError ? onClose : undefined} width={480}>
      <div style={{padding:24,display:"flex",flexDirection:"column",gap:16}}>
        <div style={{color:C.sub,fontSize:13}}>{stages[progress?.stage]||"準備中..."}</div>
        {/* Progress bar */}
        <div style={{background:"rgba(255,255,255,.08)",borderRadius:99,height:10,overflow:"hidden"}}>
          <div style={{
            height:"100%",borderRadius:99,transition:"width .3s",
            background: isError ? C.red : C.green,
            width:`${progress?.pct||0}%`,
          }}/>
        </div>
        <div style={{
          background:"rgba(0,0,0,.4)",borderRadius:10,padding:12,
          fontSize:12,color:"#86efac",fontFamily:"monospace",minHeight:60,
          maxHeight:120,overflow:"auto",
        }}>
          {progress?.msg||"請稍候..."}
        </div>
        {(isDone||isError) && (
          <div style={{display:"flex",justifyContent:"flex-end"}}>
            <Btn color={isError?"red":"green"} onClick={onClose}>
              {isError?"關閉":"開始遊戲 ▶"}
            </Btn>
          </div>
        )}
      </div>
    </Modal>
  );
}

